CASE = {'case_id': '12_repair_stitch_001_six_sheets_to_solid',
 'category': '12_repair_prepare',
 'commands': ['StitchFaces/FixGaps/FixMissingFaces/FixSplitEdges/FixExtraEdges/FixSmallFaces/FixShortEdges/FixDuplicateFaces/FixCurveGaps/FixDuplicateCurves/FixExtendableSurfaces/FixInterference '
              '.FindAndFix'],
 'expect': {'bodies': 1},
 'feature': 'rp_fix',
 'inventory_expect': None,
 'out_dir': 'D:\\training\\caedecoder\\scdm_cases\\12_repair_prepare',
 'params': {'setup': '6 planar sheets forming cube'},
 'priority': 'P2',
 'title': 'Repair: stitch, gaps, missing faces, split edges, extra edges, small faces, short edges, '
          'duplicates, merge faces: 001_six_sheets_to_solid'}


def build(ctx):
    def cube_sheets(s):
        out = []
        for ax in range(3):
            for side in (0, s):
                def pt(u, v):
                    q = [0, 0, 0]
                    q[ax] = side
                    q[(ax + 1) % 3] = u
                    q[(ax + 2) % 3] = v
                    return tuple(q)
                pts = [pt(0, 0), pt(s, 0), pt(s, s), pt(0, s)]
                n = [0, 0, 0]
                n[ax] = 1
                c = [s / 2.0] * 3
                c[ax] = side
                out.append(planar(poly_curves(pts), plane_at(tuple(c), tuple(n)), "Sheet_%s%s" % ("XYZ"[ax], "0" if side == 0 else "1")))
        return out

    sh = cube_sheets(20)
    ctx.data["sheets_before"] = len(bodies_now())
    first_ok(ctx, "stitch", [lambda: StitchFaces.FindAndFix(sel(sh)),
                             lambda: StitchFaces.FindAndFix(sel(sh), StitchOptions()),
                             lambda: StitchFaces.FindAndFix()])
    b = largest()
    intent("solid_volume_mm3", round(vol(b) or 0, 3), 8000.0, 1.0)
    intent("faces", face_count(b), 6)

if "SCDM_BATCH" not in globals():
    execfile(r"D:\training\caedecoder\scdm_cases\_framework\scdm_fw.py")
    run_standalone(CASE, build, r"D:\training\caedecoder\scdm_cases\12_repair_prepare\12_repair_stitch_001_six_sheets_to_solid.py")
